import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import '../styles/AdminDashboard.css';
import logoColor from '../assets/images/logo-warna.png'; // ← TAMBAH INI

const API_URL = 'http://localhost/web-resmi-fpg/server/api';

const AdminDashboard = () => {
    const [properties, setProperties] = useState([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [editMode, setEditMode] = useState(false);
    const [currentProperty, setCurrentProperty] = useState(null);
    const [formData, setFormData] = useState({
        title: '',
        location: '',
        type: '',
        total_blocks: 0,
        total_units: 0,
        units_sold: 0,
        units_available: 0,
        welcome_text: '',
        about_text: ''
    });
    const [mainImage, setMainImage] = useState(null);
    const [galleryImages, setGalleryImages] = useState([]);
    const [previewMainImage, setPreviewMainImage] = useState(null);
    const [activeSection, setActiveSection] = useState('properties'); // TAMBAH INI
    const [awards, setAwards] = useState([]); // TAMBAH INI
    const [awardFormData, setAwardFormData] = useState({ // TAMBAH INI
        title: '',
        year: '',
        display_order: 0
    });
    const [awardImage, setAwardImage] = useState(null); // TAMBAH INI
    const navigate = useNavigate();

    useEffect(() => {
        checkAuth();
        fetchProperties();
        fetchAwards(); // TAMBAH INI
    }, []);

    const checkAuth = () => {
        const token = localStorage.getItem('adminToken');
        if (!token) {
            navigate('/admin/login');
        }
    };

    const fetchProperties = async () => {
        try {
            const response = await axios.get(`${API_URL}/properties.php`);
            setProperties(Array.isArray(response.data) ? response.data : []);
            setLoading(false);
        } catch (error) {
            console.error('Error:', error);
            setProperties([]);
            setLoading(false);
        }
    };

    // TAMBAH FUNCTION INI
    const fetchAwards = async () => {
        try {
            const response = await axios.get(`${API_URL}/awards-list.php`);
            if (response.data.success) {
                setAwards(response.data.data);
            }
        } catch (error) {
            console.error('Error fetching awards:', error);
        }
    };

    const handleLogout = () => {
        localStorage.removeItem('adminToken');
        localStorage.removeItem('adminUser');
        navigate('/admin/login');
    };

    const handleInputChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
    };

    const handleMainImageChange = (e) => {
        const file = e.target.files[0];
        setMainImage(file);
        if (file) {
            setPreviewMainImage(URL.createObjectURL(file));
        }
    };

    const handleGalleryImagesChange = (e) => {
        setGalleryImages(Array.from(e.target.files));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        const token = localStorage.getItem('adminToken');
        const formDataToSend = new FormData();
        
        Object.keys(formData).forEach(key => {
            formDataToSend.append(key, formData[key]);
        });
        
        if (mainImage) {
            formDataToSend.append('mainImage', mainImage);
        }
        
        galleryImages.forEach((image) => {
            formDataToSend.append('galleryImages[]', image);
        });

        try {
            if (editMode && currentProperty) {
                formDataToSend.append('id', currentProperty.id);
                await axios.post(
                    `${API_URL}/property-update.php`,
                    formDataToSend,
                    {
                        headers: {
                            'Content-Type': 'multipart/form-data',
                            'Authorization': `Bearer ${token}`
                        }
                    }
                );
                alert('Property updated successfully!');
            } else {
                await axios.post(
                    `${API_URL}/property-create.php`,
                    formDataToSend,
                    {
                        headers: {
                            'Content-Type': 'multipart/form-data',
                            'Authorization': `Bearer ${token}`
                        }
                    }
                );
                alert('Property created successfully!');
            }
            
            closeModal();
            fetchProperties();
        } catch (error) {
            console.error('Error:', error);
            alert(error.response?.data?.message || 'Failed to save property');
        }
    };

    const handleEdit = (property) => {
        setEditMode(true);
        setCurrentProperty(property);
        setFormData({
            title: property.title,
            location: property.location,
            type: property.type,
            total_blocks: property.total_blocks || 0,
            total_units: property.total_units || 0,
            units_sold: property.units_sold || 0,
            units_available: property.units_available || 0,
            welcome_text: property.welcome_text || '',
            about_text: property.about_text || ''
        });
        setPreviewMainImage(property.image || property.main_image);
        setShowModal(true);
    };

    const handleDelete = async (id) => {
        if (!window.confirm('Are you sure you want to delete this property?')) {
            return;
        }

        const token = localStorage.getItem('adminToken');
        
        try {
            await axios.delete(
                `${API_URL}/property-delete.php?id=${id}`,
                {
                    headers: {
                        'Authorization': `Bearer ${token}`
                    }
                }
            );
            alert('Property deleted successfully!');
            fetchProperties();
        } catch (error) {
            console.error('Error:', error);
            alert('Failed to delete property');
        }
    };

    // TAMBAH FUNCTION INI
    const handleAwardInputChange = (e) => {
        const { name, value } = e.target;
        setAwardFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    // TAMBAH FUNCTION INI
    const handleAwardImageChange = (e) => {
        if (e.target.files && e.target.files[0]) {
            setAwardImage(e.target.files[0]);
        }
    };

    // TAMBAH FUNCTION INI
    const handleAwardSubmit = async (e) => {
        e.preventDefault();
        
        const formData = new FormData();
        formData.append('title', awardFormData.title);
        formData.append('year', awardFormData.year);
        formData.append('display_order', awardFormData.display_order);
        if (awardImage) {
            formData.append('image', awardImage);
        }

        try {
            const response = await axios.post(`${API_URL}/award-create.php`, formData, {
                headers: { 'Content-Type': 'multipart/form-data' }
            });

            if (response.data.success) {
                alert('Award added successfully!');
                fetchAwards();
                setShowModal(false);
                setAwardFormData({ title: '', year: '', display_order: 0 });
                setAwardImage(null);
            }
        } catch (error) {
            alert('Error adding award: ' + (error.response?.data?.message || error.message));
        }
    };

    // TAMBAH FUNCTION INI
    const handleDeleteAward = async (id) => {
        if (!window.confirm('Are you sure you want to delete this award?')) return;

        try {
            const response = await axios.delete(`${API_URL}/award-delete.php?id=${id}`);
            if (response.data.success) {
                alert('Award deleted successfully!');
                fetchAwards();
            }
        } catch (error) {
            alert('Error deleting award: ' + (error.response?.data?.message || error.message));
        }
    };

    const openModal = () => {
        setShowModal(true);
        setEditMode(false);
        setCurrentProperty(null);
        setFormData({
            title: '',
            location: '',
            type: '',
            total_blocks: 0,
            total_units: 0,
            units_sold: 0,
            units_available: 0,
            welcome_text: '',
            about_text: ''
        });
        setMainImage(null);
        setGalleryImages([]);
        setPreviewMainImage(null);
        setAwardFormData({ title: '', year: '', display_order: 0 });
        setAwardImage(null);
    };

    const closeModal = () => {
        setShowModal(false);
        setEditMode(false);
        setCurrentProperty(null);
        setFormData({
            title: '',
            location: '',
            type: '',
            total_blocks: 0,
            total_units: 0,
            units_sold: 0,
            units_available: 0,
            welcome_text: '',
            about_text: ''
        });
        setMainImage(null);
        setGalleryImages([]);
        setPreviewMainImage(null);
        setAwardFormData({ title: '', year: '', display_order: 0 });
        setAwardImage(null);
    };

    if (loading) {
        return (
            <div className="loading">
                <div className="loading-spinner"></div>
                <p>Loading...</p>
            </div>
        );
    }

    return (
        <div className="admin-dashboard">
            {/* UPDATE HEADER INI */}
            <header className="admin-header">
                <div className="admin-header-left">
                    <div className="admin-logo">
                        <img src={logoColor} alt="Fachri Property Group" />
                        <div className="admin-header-content">
                            <h1>Admin Dashboard</h1>
                        </div>
                    </div>
                </div>
                <div className="admin-actions">
                    {/* TAMBAHKAN CONDITIONAL BUTTON INI */}
                    {activeSection === 'properties' ? (
                        <button className="btn-add" onClick={openModal}>
                            <span>+</span> Add New Property
                        </button>
                    ) : (
                        <button className="btn-add" onClick={openModal}>
                            <span>+</span> Add New Award
                        </button>
                    )}
                    <button className="btn-logout" onClick={handleLogout}>
                        Logout
                    </button>
                </div>
            </header>

            {/* TAMBAH NAVIGATION TABS */}
            <div className="admin-navigation">
                <button 
                    className={activeSection === 'properties' ? 'nav-btn active' : 'nav-btn'}
                    onClick={() => setActiveSection('properties')}
                >
                    Properties
                </button>
                <button 
                    className={activeSection === 'awards' ? 'nav-btn active' : 'nav-btn'}
                    onClick={() => setActiveSection('awards')}
                >
                    Awards
                </button>
            </div>

            {/* PROPERTIES SECTION */}
            {activeSection === 'properties' && (
                <>
                    <div className="dashboard-stats">
                        <div className="stat-card">
                            <h3>{properties.length}</h3>
                            <p>Total Properties</p>
                        </div>
                        <div className="stat-card">
                            <h3>{properties.filter(p => p.type === 'Tipe 36').length}</h3>
                            <p>Tipe 36</p>
                        </div>
                        <div className="stat-card">
                            <h3>{properties.filter(p => p.type === 'Tipe 40').length}</h3>
                            <p>Tipe 40</p>
                        </div>
                        <div className="stat-card">
                            <h3>{properties.filter(p => p.type === 'Tipe 50').length}</h3>
                            <p>Tipe 50</p>
                        </div>
                        <div className="stat-card">
                            <h3>{properties.filter(p => p.type === 'Tipe 60').length}</h3>
                            <p>Tipe 60</p>
                        </div>
                    </div>

                    <div className="properties-table-container">
                        <h2>All Properties</h2>
                        {properties.length > 0 ? (
                            <table className="properties-table">
                                <thead>
                                    <tr>
                                        <th>Image</th>
                                        <th>Title</th>
                                        <th>Location</th>
                                        <th>Type</th>
                                        <th>Actions</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {properties.map(property => (
                                        <tr key={property.id}>
                                            <td>
                                                <img 
                                                    src={property.image || property.main_image} 
                                                    alt={property.title}
                                                    className="table-image"
                                                />
                                            </td>
                                            <td>{property.title}</td>
                                            <td>{property.location}</td>
                                            <td><span className="badge">{property.type}</span></td>
                                            <td>
                                                <div className="action-buttons">
                                                    <button 
                                                        className="btn-edit"
                                                        onClick={() => handleEdit(property)}
                                                    >
                                                        Edit
                                                    </button>
                                                    <button 
                                                        className="btn-delete"
                                                        onClick={() => handleDelete(property.id)}
                                                    >
                                                        Delete
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        ) : (
                            <div className="no-data">
                                <p>No properties found. Click "Add New Property" to create one.</p>
                            </div>
                        )}
                    </div>
                </>
            )}

            {/* AWARDS SECTION */}
            {activeSection === 'awards' && (
                <>
                    <div className="awards-stats">
                        <div className="stat-card">
                            <h3>{awards.length}</h3>
                            <p>Total Awards</p>
                        </div>
                    </div>

                    <div className="awards-table-container">
                        <h2>Awards Management</h2>
                        {awards.length === 0 ? (
                            <div className="no-data">
                                <p>No awards found. Add your first award!</p>
                            </div>
                        ) : (
                            <table className="properties-table">
                                <thead>
                                    <tr>
                                        <th>Image</th>
                                        <th>Title</th>
                                        <th>Year</th>
                                        <th>Order</th>
                                        <th>Actions</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {awards.map((award) => (
                                        <tr key={award.id}>
                                            <td>
                                                <img 
                                                    src={award.image} 
                                                    alt={award.title}
                                                    className="table-image"
                                                    onError={(e) => {
                                                        e.target.src = 'https://via.placeholder.com/80x60?text=Award';
                                                    }}
                                                />
                                            </td>
                                            <td>{award.title}</td>
                                            <td>{award.year || '-'}</td>
                                            <td>{award.display_order}</td>
                                            <td>
                                                <div className="action-buttons">
                                                    <button 
                                                        className="btn-delete"
                                                        onClick={() => handleDeleteAward(award.id)}
                                                    >
                                                        Delete
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        )}
                    </div>
                </>
            )}

            {/* MODAL - UPDATE INI */}
            {showModal && (
                <div className="modal-overlay" onClick={closeModal}>
                    <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                        <div className="modal-header">
                            <h2>
                                {activeSection === 'properties' 
                                    ? (editMode ? 'Edit Property' : 'Add New Property')
                                    : 'Add New Award'
                                }
                            </h2>
                            <button className="close-btn" onClick={closeModal}>&times;</button>
                        </div>
                        
                        {activeSection === 'properties' ? (
                            <form onSubmit={handleSubmit}>
                                {/* Row 1: Title & Type */}
                                <div className="form-row">
                                    <div className="form-group">
                                        <label>Title *</label>
                                        <input
                                            type="text"
                                            name="title"
                                            value={formData.title}
                                            onChange={handleInputChange}
                                            placeholder="Enter property title"
                                            required
                                        />
                                    </div>

                                    <div className="form-group">
                                        <label>Type *</label>
                                        <select
                                            name="type"
                                            value={formData.type}
                                            onChange={handleInputChange}
                                            required
                                        >
                                            <option value="">Select Type</option>
                                            <option value="Tipe 36">Tipe 36</option>
                                            <option value="Tipe 40">Tipe 40</option>
                                            <option value="Tipe 50">Tipe 50</option>
                                            <option value="Tipe 60">Tipe 60</option>
                                            
                                        </select>
                                    </div>
                                </div>

                                {/* Location */}
                                <div className="form-group">
                                    <label>Location *</label>
                                    <input
                                        type="text"
                                        name="location"
                                        value={formData.location}
                                        onChange={handleInputChange}
                                        placeholder="Enter location"
                                        required
                                    />
                                </div>

                                {/* Row 2: Total Blok & Total Unit */}
                                <div className="form-row">
                                    <div className="form-group">
                                        <label>Total Blok</label>
                                        <input
                                            type="number"
                                            name="total_blocks"
                                            value={formData.total_blocks}
                                            onChange={handleInputChange}
                                            placeholder="5"
                                            min="0"
                                        />
                                    </div>

                                    <div className="form-group">
                                        <label>Total Unit</label>
                                        <input
                                            type="number"
                                            name="total_units"
                                            value={formData.total_units}
                                            onChange={handleInputChange}
                                            placeholder="120"
                                            min="0"
                                        />
                                    </div>
                                </div>

                                {/* Row 3: Unit Terjual & Unit Tersedia */}
                                <div className="form-row">
                                    <div className="form-group">
                                        <label>Unit Terjual</label>
                                        <input
                                            type="number"
                                            name="units_sold"
                                            value={formData.units_sold}
                                            onChange={handleInputChange}
                                            placeholder="85"
                                            min="0"
                                        />
                                    </div>

                                    <div className="form-group">
                                        <label>Unit Tersedia</label>
                                        <input
                                            type="number"
                                            name="units_available"
                                            value={formData.units_available}
                                            onChange={handleInputChange}
                                            placeholder="35"
                                            min="0"
                                        />
                                    </div>
                                </div>

                                {/* Welcome Text */}
                                <div className="form-group">
                                    <label>Welcome Text</label>
                                    <input
                                        type="text"
                                        name="welcome_text"
                                        value={formData.welcome_text}
                                        onChange={handleInputChange}
                                        placeholder="Selamat datang di PT FACHRI PROPERTY GROUP"
                                    />
                                </div>

                                {/* About Text */}
                                <div className="form-group">
                                    <label>About Text</label>
                                    <textarea
                                        name="about_text"
                                        value={formData.about_text}
                                        onChange={handleInputChange}
                                        placeholder="Borneo Real Properti Adalah Perusahaan..."
                                        rows="4"
                                    />
                                </div>

                                {/* Main Image */}
                                <div className="form-group">
                                    <label>Main Image {editMode && '(Leave empty to keep current)'}</label>
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={handleMainImageChange}
                                    />
                                    {previewMainImage && (
                                        <div className="image-preview">
                                            <img src={previewMainImage} alt="Preview" />
                                        </div>
                                    )}
                                </div>

                                {/* Gallery Images */}
                                <div className="form-group">
                                    <label>Gallery Images (Multiple)</label>
                                    <input
                                        type="file"
                                        accept="image/*"
                                        multiple
                                        onChange={handleGalleryImagesChange}
                                    />
                                    <small>You can select multiple images</small>
                                </div>

                                <div className="form-actions">
                                    <button type="button" className="btn-cancel" onClick={closeModal}>
                                        Cancel
                                    </button>
                                    <button type="submit" className="btn-submit">
                                        {editMode ? 'Update' : 'Create'} Property
                                    </button>
                                </div>
                            </form>
                        ) : (
                            <form onSubmit={handleAwardSubmit}>
                                <div className="form-group">
                                    <label>Title *</label>
                                    <input
                                        type="text"
                                        name="title"
                                        value={awardFormData.title}
                                        onChange={handleAwardInputChange}
                                        placeholder="Enter award title"
                                        required
                                    />
                                </div>

                                <div className="form-group">
                                    <label>Year</label>
                                    <input
                                        type="text"
                                        name="year"
                                        value={awardFormData.year}
                                        onChange={handleAwardInputChange}
                                        placeholder="2024"
                                    />
                                </div>

                                <div className="form-group">
                                    <label>Display Order</label>
                                    <input
                                        type="number"
                                        name="display_order"
                                        value={awardFormData.display_order}
                                        onChange={handleAwardInputChange}
                                        placeholder="0"
                                    />
                                    <small>Lower number = displayed first</small>
                                </div>

                                <div className="form-group">
                                    <label>Award Image *</label>
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={handleAwardImageChange}
                                        required
                                    />
                                </div>

                                <div className="form-actions">
                                    <button type="button" className="btn-cancel" onClick={closeModal}>
                                        Cancel
                                    </button>
                                    <button type="submit" className="btn-submit">
                                        Create Award
                                    </button>
                                </div>
                            </form>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default AdminDashboard;
